-- Volcando estructura para tabla vitridb.entradas
CREATE TABLE IF NOT EXISTS `entradas` (
  `id_entrada` int NOT NULL AUTO_INCREMENT,
  `fecha_creacion` datetime NOT NULL,
  `entrada_productos` int NOT NULL,
  `entrada_cantidad` decimal(10,2) NOT NULL,
  `observacion` varchar(1000) NOT NULL,
  `entrada_usuario` int NOT NULL,
  PRIMARY KEY (`id_entrada`),
  KEY `entrada_productos` (`entrada_productos`),
  KEY `entrada_usuario` (`entrada_usuario`),
  CONSTRAINT `entradas_ibfk_1` FOREIGN KEY (`entrada_productos`) REFERENCES `productos` (`id`),
  CONSTRAINT `entradas_ibfk_2` FOREIGN KEY (`entrada_usuario`) REFERENCES `usuarios` (`id_usuarios`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Volcando datos para la tabla vitridb.entradas: ~71 rows (aproximadamente)
