-- Volcando estructura para tabla vitridb.pedidos
CREATE TABLE IF NOT EXISTS `pedidos` (
  `id_pedidos` int NOT NULL AUTO_INCREMENT,
  `monto_total` decimal(10,2) NOT NULL,
  `estado_pedido` enum('APROBADO','CANCELADO','PENDIENTE','ENTREGADO','DEVUELTO') NOT NULL,
  `fecha_creacion` datetime NOT NULL,
  `id_usuarios` int NOT NULL,
  `direccion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `forma_entrega` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `barrio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `ciudad` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (`id_pedidos`),
  KEY `id_usuarios` (`id_usuarios`),
  CONSTRAINT `pedidos_ibfk_1` FOREIGN KEY (`id_usuarios`) REFERENCES `usuarios` (`id_usuarios`)
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

