CREATE TABLE IF NOT EXISTS `pedidos_productos` (
  `id_pedidos_productos` int NOT NULL AUTO_INCREMENT,
  `cantidad` decimal(10,2) NOT NULL,
  `precio` decimal(10,2) NOT NULL,
  `fecha_creacion` datetime NOT NULL,
  `fecha_actualizacion` datetime NOT NULL,
  `id_pedidos` int NOT NULL,
  `id` int NOT NULL,
  `cantidad_producto` decimal(10,2) NOT NULL,
  `unidad_producto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `nombre_producto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (`id_pedidos_productos`),
  KEY `id_pedidos` (`id_pedidos`),
  KEY `id` (`id`),
  CONSTRAINT `pedidos_productos_ibfk_1` FOREIGN KEY (`id_pedidos`) REFERENCES `pedidos` (`id_pedidos`),
  CONSTRAINT `pedidos_productos_ibfk_2` FOREIGN KEY (`id`) REFERENCES `productos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=120 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

