-- Volcando estructura para tabla vitridb.productos
CREATE TABLE IF NOT EXISTS `productos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sku` varchar(255) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `descripcion` varchar(1000) NOT NULL,
  `url_imagen` varchar(255) NOT NULL,
  `url_ficha_tecnica` varchar(255) NOT NULL,
  `unidad_producto` enum('KG','GR','L','ML','UND') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cantidad` int NOT NULL,
  `max_usuario` int NOT NULL,
  `precio` float NOT NULL,
  `is_promocion` tinyint(1) NOT NULL,
  `anunciar` int NOT NULL,
  `stock` int NOT NULL,
  `is_activo` tinyint(1) NOT NULL,
  `descuento` decimal(10,2) NOT NULL,
  `fecha_inicio_descuento` date NOT NULL,
  `fecha_fin_descuento` date NOT NULL,
  `fecha_creacion` datetime NOT NULL,
  `fecha_actualizacion` datetime NOT NULL,
  `id_categorias` int NOT NULL,
  `id_usuarios` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sku` (`sku`),
  KEY `id_categorias` (`id_categorias`),
  KEY `id_usuarios` (`id_usuarios`),
  CONSTRAINT `productos_ibfk_1` FOREIGN KEY (`id_categorias`) REFERENCES `categorias` (`id_categorias`),
  CONSTRAINT `productos_ibfk_2` FOREIGN KEY (`id_usuarios`) REFERENCES `usuarios` (`id_usuarios`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Volcando datos para la tabla vitridb.productos: ~34 rows (aproximadamente)
INSERT INTO `productos` (`id`, `sku`, `nombre`, `descripcion`, `url_imagen`, `url_ficha_tecnica`, `unidad_producto`, `cantidad`, `max_usuario`, `precio`, `is_promocion`, `anunciar`, `stock`, `is_activo`, `descuento`, `fecha_inicio_descuento`, `fecha_fin_descuento`, `fecha_creacion`, `fecha_actualizacion`, `id_categorias`, `id_usuarios`) VALUES
	(1, 'Cachama', 'Cachama', 'Pescado de agua dulce, ideal para asar o preparar al horno.', 'https://medicinayproduccionacuicola.wordpress.com/wp-content/uploads/2017/11/csm_agencianoticias-20170606-01_08_72e00a7d07.jpg', 'https://medicinayproduccionacuicola.wordpress.com/wp-content/uploads/2017/11/csm_agencianoticias-20170606-01_08_72e00a7d07.jpg', 'KG', 1, 0, 9000, 0, 1, 103, 1, 15.00, '2024-09-05', '2024-09-05', '2024-09-09 10:45:23', '2026-02-06 16:12:32', 1, 1),
	(2, 'Tilapia roja', 'Tilapia roja', 'Pescado blanco y suave, perfecto para freír o cocinar al vapor.', 'https://static.vecteezy.com/system/resources/previews/006/413/221/non_2x/raw-red-tilapia-fish-is-a-kind-of-freshwater-fish-consumption-served-on-white-plate-with-spices-and-lemon-selected-focus-free-photo.JPG', 'https://cdn.croper.com/images/rpm14bdbh3lw9bz291uwh/original.jpeg', 'KG', 1, 0, 9000, 0, 1, 100, 1, 15.00, '2024-09-07', '2024-09-07', '2024-09-09 10:45:23', '2025-12-18 10:03:53', 1, 1),
	(20, 'Huevos', 'canasta de huevo', 'Fuente rica de proteína, versátiles en la cocina, se pueden preparar de muchas formas.', 'https://static.wixstatic.com/media/75c13d_928bbcd1c7d641e99d133854c1d7e335~mv2_d_2122_1415_s_2.jpg/v1/fit/w_500,h_500,q_90/file.jpg', 'https://i.pinimg.com/236x/b1/4f/2e/b14f2eb0a8363fb9d06f9ee880f6b3be.jpg', 'UND', 30, 3, 12000, 1, 1, 135, 1, 15.00, '2024-08-13', '2024-08-13', '2024-09-09 10:45:23', '2026-04-16 07:48:22', 2, 1),
	(24, 'Helado', 'Helado', 'Postre frío y cremoso, disponible en varios sabores, ideal para el calor.', 'https://media.istockphoto.com/id/855447930/es/foto/vario-de-helado-sabor-en-ar%C3%A1ndanos-de-conos-fresa-pistacho-configuraci%C3%B3n-de-almendra-naranja-y.jpg?s=612x612&w=0&k=20&c=A05sOz754OiHIshJmoVzhRbl4p8ZYfhbOY5R6IokEcM=', 'https://i.pinimg.com/236x/42/54/82/42548261f3279f614eca18b51aecca96.jpg', 'GR', 1, 0, 1000, 1, 0, 99, 1, 15.00, '2024-09-06', '2024-09-06', '2024-09-09 10:45:23', '2026-04-16 07:48:31', 2, 1),
	(25, 'Leche de vaca', 'Leche de vaca', 'Lácteo esencial, rica en calcio, ideal para bebidas y cocina.', 'https://rumiantes.com/wp-content/uploads/2022/01/dreamstime_l_33132448-scaled.jpg', 'https://i.pinimg.com/736x/f5/f9/54/f5f954b40d42eff2d7a837b273644446.jpg', 'L', 1, 2, 1500, 0, 0, 100, 1, 15.00, '2024-09-07', '2024-09-07', '2024-09-09 10:45:23', '2025-08-10 23:13:21', 2, 1),
