-- Volcando estructura para tabla vitridb.salidas
CREATE TABLE IF NOT EXISTS `salidas` (
  `id_salidas` int NOT NULL AUTO_INCREMENT,
  `fecha_creacion` datetime NOT NULL,
  `salidas_productos` int NOT NULL,
  `salidas_cantidad` decimal(10,2) NOT NULL,
  `observacion` varchar(1000) NOT NULL,
  `salidas_usuario` int NOT NULL,
  `salidas_estado` enum('DESCOMPUESTO','ROBO','VENCIDO','DONACION','ERROR') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (`id_salidas`),
  KEY `salidas_productos` (`salidas_productos`),
  KEY `salidas_usuario` (`salidas_usuario`),
  CONSTRAINT `salidas_ibfk_1` FOREIGN KEY (`salidas_productos`) REFERENCES `productos` (`id`),
  CONSTRAINT `salidas_ibfk_2` FOREIGN KEY (`salidas_usuario`) REFERENCES `usuarios` (`id_usuarios`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

